// Runtime-agnostic WebSocket transport. Uses the global `WebSocket` in
// browsers / Deno / Bun / Node ≥21, and dynamically imports the `ws` package
// in older Node (≥18 < 21) where the global is missing.

/** A value the transport can put on the wire. Strings are JSON control/data
 * frames; binary values are pre-encoded channel binary frames. */
export type WsSendData = string | ArrayBufferLike | ArrayBufferView;

export interface WsLike {
  readonly readyState: number;
  /** Set to `"arraybuffer"` so inbound binary frames arrive as ArrayBuffers
   * (uniform across the global WebSocket and the `ws` package). */
  binaryType?: string;
  send(data: WsSendData): void;
  close(code?: number, reason?: string): void;
  addEventListener(type: "open", listener: () => void): void;
  addEventListener(type: "message", listener: (ev: { data: unknown }) => void): void;
  addEventListener(type: "close", listener: (ev: { code: number; reason: string }) => void): void;
  addEventListener(type: "error", listener: (ev: unknown) => void): void;
}

export const WS_OPEN = 1;

/** Force binary frames to surface as ArrayBuffer on whichever WS impl we got. */
function preferArrayBuffer(ws: WsLike): void {
  try {
    ws.binaryType = "arraybuffer";
  } catch {
    /* some impls reject the assignment pre-open; the channel decoder also
       accepts Uint8Array / Blob, so this is best-effort. */
  }
}

export async function openWebSocket(url: string): Promise<WsLike> {
  const globalAny = globalThis as unknown as { WebSocket?: new (url: string) => WsLike };
  const Ctor = globalAny.WebSocket;
  if (typeof Ctor === "function") {
    const ws = new Ctor(url);
    preferArrayBuffer(ws);
    return ws;
  }
  // Node fallback: dynamic import. Importer must have `ws` installed.
  // We can't statically import `ws` because it would force a dep in the
  // browser path. The `peerDependencies` declaration in package.json marks it
  // optional.
  let mod: { default: new (url: string) => WsLike };
  try {
    mod = (await import(/* @vite-ignore */ "ws")) as {
      default: new (url: string) => WsLike;
    };
  } catch (e) {
    throw new Error(
      "hoody-sdk: no global WebSocket and the optional `ws` " +
        "package is not installed. Either upgrade to Node ≥21 (which has " +
        "a global WebSocket) or `npm install ws`. Original error: " +
        (e instanceof Error ? e.message : String(e)),
    );
  }
  const ws = new mod.default(url);
  preferArrayBuffer(ws);
  return ws;
}


